    if (method === "GET" && u.pathname.startsWith("/d2l/") && !u.pathname.startsWith("/d2l/bsx/")) return reply(200, "text/html; charset=utf-8", "<!doctype html><title>Brightspace</title><p>Original Brightspace page (not part of this demo).</p>");
