  const imageFor = (src) => { try { const u = new URL(src, location.href); if (u.origin !== location.origin || !u.pathname.startsWith("/d2l/api/")) return src; const r = F.handle(u.pathname, u.searchParams); return r && String(r.type).startsWith("image/") ? "data:" + r.type + ";charset=utf-8," + encodeURIComponent(r.body) : src; } catch { return src; } };
